function parseTerm(str) {
  if (!str) return '';
  const re = /^(sin|cos|arccot|cot|tan|sec|csc|ln|exp|det|arcsin|arccos|arctan|arccot|arccsc|arcsec|min|max|arg|dim|ker|det|trace|range|sqn|Aut|Hom|Mor|Ob|Iso|End|Inn|Out|GL|SL|SO|Tor|Ext|Ann|Ass|Div|Pic|Spec|Proj|Ker|dom|codom|lcm|lcf|gcd|hcf|gcf|sign|const|log|deg|rad|hom|coker|nil|Nil|jac|Jac|codim|disc|adj|Range|rank|Rank|Nul|Col|Row|Span|diag|Image|card|Perv|Var|Isom|Map|Nat|Lan|Ran|Arr|Sh|PShDesc|Fib|DFib|Gr|Fact|TS|Tot|Res|gr|rk|cf|Cone|Cocone|Disc|Bun|Rep|Ind|Coind|Alt|Mult|calP|BC|Ht|nul|trdeg|inr|Sub|Fam|H|Ch|CoCh|Comp|Ho|inf|sup|tr|im|cl|Sp|Pr)?(ds|sf|bb|bs|bf|bm|rm|cal|scr|frk)?(alpha|beta|gamma|delta|zeta|eta|varepsilon|theta|iota|kappa|vartheta|lambda|nu|pi|tau|upsilon|phi|chi|psi|omega|Gamma|Delta|Theta|Lambda|Xi|Pi|Sigma|Upsilon|Phi|Psi|Omega|[A-Za-z0-9])('*|\*+|\d+|_[A-Za-z0-9]+)?(ovl|udl|ovb|udb|bar|bre|hat|til|dot|vec|itr|conj|trans|what|wtil|sqr)?$/;
  const p = str.match(re);
  if (!p) return str;
  const fn = p[1] || '';
  const font = p[2] || '';
  const base = p[3] || '';
  const sub = p[4] || '';
  const acc = p[5] || '';
  const isGreek = /^(alpha|beta|gamma|delta|zeta|eta|varepsilon|theta|iota|kappa|vartheta|lambda|nu|pi|tau|upsilon|phi|chi|psi|omega|Gamma|Delta|Theta|Lambda|Xi|Pi|Sigma|Upsilon|Phi|Psi|Omega)$/.test(base);
  let atom = isGreek ? ('\\' + base) : base;
  if (font) atom = '\\' + font + '{' + atom + '}';
  if (acc) atom = '\\' + acc + '{' + atom + '}';
  if (sub) {
    if (sub.startsWith("'")) atom += sub;
    else if (sub === '*') atom += '_*';
    else if (sub.startsWith('_')) atom += sub;
    else if (sub.length === 1) atom += '_' + sub;
    else atom += '_{' + sub + '}';
  }
  return fn ? ('\\' + fn + '(' + atom + ')') : atom;
}

const delimiter = splitInlineDelimiter(m[2] || '');
let open = m[1] ? delimiter.whitespace : delimiter.whitespace + '\\$';
open += delimiter.comma;

const left = parseTerm(m[3]);
const op = '\\' + m[5];
const mod = m[6] || '';
const mid = parseTerm(m[7] || '');
const right = parseTerm(m[8] || m[9] || '');

let middle = '';
if (mod) {
  const modMap = {
    ud: '_{' + mid + '}',
    ov: '^{' + mid + '}',
    uo: '_{' + mid + '}^{$1}',
    ou: '^{' + mid + '}_{$1}'
  };
  const modStr = modMap[mod] || '';
  middle = op + modStr + (right ? (right.startsWith('\\') ? right : ' ' + right) : '');
} else {
  middle = right ? (op + (right.startsWith('\\') ? right : ' ' + right)) : op;
}

rv = open + left + middle + '\\$' + (m[10] || '') + '$0';
